/**
 * dsh-mcp-servers — pipeline/timeout：调用超时兜底（#664 阶段 2 迁入）。
 *
 * 原自 middleware-utils.ts withTimeout；中间层 ws_mcp_call 与封装直呼的
 * abort 竞态处理单一实现（supervisor 路径靠 SDK timeoutMs，无此层）。
 */

/** 等待带超时（race 兜底）。 */
export function withTimeout<T>(promise: Promise<T>, ms: number, message: string, signal?: AbortSignal): Promise<T> {
  if (signal?.aborted === true) return Promise.reject(signal.reason ?? new Error("aborted"));
  return new Promise<T>((resolve, reject) => {
    const timer = setTimeout(() => {
      cleanup();
      reject(new Error(message));
    }, ms);
    const onAbort = () => {
      cleanup();
      reject(signal?.reason ?? new Error("aborted"));
    };
    const cleanup = () => {
      clearTimeout(timer);
      signal?.removeEventListener("abort", onAbort);
    };
    signal?.addEventListener("abort", onAbort, { once: true });
    void promise.then(
      (value) => {
        cleanup();
        resolve(value);
      },
      (error) => {
        cleanup();
        reject(error);
      },
    );
  });
}

packages/dsh-mcp-servers/src/catalog/dig.source:
/**
 * dsh-mcp-servers — catalog/digest.ts：目录条目 digest（#664 阶段 5）。
 *
 * 自 src/catalog.ts 拆出（digest 域）：sha256 摘要，**只含服务器集合（name），
 * 不含描述文本**——工具描述不稳定（按需注册/动态描述），含描述会永远追不上
 * 抖动触发替换注入；只含 name 后服务器增删才触发替换。
 */

import { createHash } from "node:crypto";
import type { CatalogEntry } from "./entries.ts";

/**
 * 目录条目 digest（sha256）——**只含服务器集合（name），不含描述文本**。
 *
 * 为什么：MCP 服务器的工具描述集合不稳定（按需注册/动态描述，实测 code-graph
 * 等服务器不同时刻的摘要都不同）。若 digest 含描述文本，缓存摘要一更新就触发
 * 替换注入——永远追不上抖动。digest 只含 name 后：
 * - 服务器增删 → digest 变 → 原位替换（合理）
 * - 描述/缓存更新 → digest 不变 → 本会话目录保持快照（静态能力地图语义，
 *   与消息声明"仅描述能力、不代表当前连接状态"一致），跨会话才反映新缓存
 */
export function digestCatalogEntries(entries: CatalogEntry[]): string {
  const canonical = entries.map((entry) => entry.name).join("\n");
  return createHash("sha256").update(canonical).digest("hex");
}

packages/dsh-mcp-servers/src/catalog/his.source:
/**
 * dsh-mcp-servers — catalog/history.ts：会话内目录历史定位（#664 阶段 5）。
 *
 * 自 src/catalog.ts 拆出（history 域）：从会话持久化日志倒序找最后一条**可见**
 * 的能力目录消息——目录注入去重的权威来源。新旧两代 source 形态都认（#723）。
 */

import { digestCatalogEntries } from "./digest.ts";
import { isCatalogSource, resolveCatalogEntries } from "./entries.ts";
import type { CatalogSourceLike } from "./entries.ts";

/** 目录历史查询结果。 */
export interface CatalogHistoryResult {
  visibleDigest?: string;
  published: boolean;
}

/** agent 最小面（session.snapshotEvents() 倒序找目录消息；0.1.2-rc.1 起 events getter 移除）。 */
export interface CatalogAgent {
  session?: {
    surface?: { nodes?: unknown[] };
    snapshotEvents?: () => ReadonlyArray<{ type?: string; seq?: unknown; data?: { source?: CatalogSourceLike } }>;
  };
}

/**
 * 从会话持久化日志（agent.session.snapshotEvents()）倒序找最后一条**可见**的
 * 能力目录消息。**这是去重的权威来源**（与官方 dsh-tool-skill catalogHistory
 * 同构）：
 * - decision.messages 只含本轮新消息，历史目录消息不在其中——用它定位会导致每轮重复注入；
 * - 可见性（surface.nodes）过滤：compaction/resume 后旧目录不可见 → visibleDigest 为空 → 重新注入；
 * - 新旧两代 source 形态共存（#723 升级前的会话仍是 mcp-catalog + entries）。
 */
export function catalogHistory(agent: CatalogAgent | undefined): CatalogHistoryResult {
  const visible = new Set(agent?.session?.surface?.nodes ?? []);
  const events = agent?.session?.snapshotEvents?.() ?? [];
  let published = false;
  for (let index = events.length - 1; index >= 0; index -= 1) {
    const event = events[index];
    if (event?.type !== "user/message") continue;
    if (!isCatalogSource(event.data?.source)) continue;
    const entries = resolveCatalogEntries(event.data?.source);
    if (entries === undefined) continue;
    published = true;
    if (visible.has(event.seq)) return { visibleDigest: digestCatalogEntries(entries), published };
  }
  return { published };
}

