    await pollUntil("心跳 data ping 帧到达", () => countPing(res) >= 1);
    const pingsAtClose = countPing(res);
    // close：hub 内部 evict（出表 + 停对该连接写心跳），此后不再有新帧。
    res.state.onClose();
