  it("null 入参抛 must be an object", () => {
    expect(() => normalizeServer(null)).toThrow(/must be an object/);
  });

  it("缺 name 抛 server name must match", () => {
    expect(() => normalizeServer({ transport: "stdio" })).toThrow(/server name must match/);
