    expect(manager.runtimeRegistry.has("cg")).toBe(false);
  });

  it("虚拟连接已拆", async () => {
    const { mw } = await registered({ unregister: true });
    expect(mw.units.get("@global")?.connections.has("cg")).toBe(false);
  });

  it("目录条目已清（防幽灵）", async () => {
    const { mw } = await registered({ unregister: true });
    expect(mw.units.get("@global")?.catalog.has("cg")).toBe(false);
  });
});

