describe("中间层模式 connect/disconnect 分支（#228）", () => {
  async function middlewareConnected() {
    const { dir, manager, store } = managerFixture("dsh-mcp-mgr2t-");
    store.upsert(normalizeServer(quietServer("g1")));
    const proj = join(dir, "proj");
