    expect(mw.units.get(proj).userDisabled.has("p1")).toBe(false);
  });

  it("断开后 userDisabled", async () => {
    // 项目级 disconnect → userDisabled 持久化。
    const { manager, mw, proj } = await middlewareConnected();
    await manager.disconnect("p1");
