    const ctx = baseCtx({
      inject: (keys, cb) => {
        if (Array.isArray(keys) && keys.includes("settings")) {
          cb({
            settings: {
              update: function(ns, patch) {
                refs.updateCalled = true;
                refs.updateNs = ns;
                refs.updatePatch = patch;
                return Promise.resolve();
              },
              register: () => {
