describe("MCPClient.initialize：失败路径（命令不存在，stderrTail 空）", () => {
  it("stderrTail 非空 ⇔ 错误消息附 stderr 后缀（跨平台不变式）", async () => {
    const transport = new StdioTransport({ command: "dsh-mcp-missing-cmd-xyz" });
    const client = new MCPClient(transport);
    const err = await client.initialize().then(() => null, (e) => e);
    expect(err).toBeInstanceOf(Error);
    // Windows：cross-spawn 经 cmd.exe 兜底执行，stderr 会先收到「不是内部或外部
    // 命令」提示——此时附 stderr 后缀正是诊断语义（GBK 控制台为乱码但不影响
    // 不变式）；POSIX 下 ENOENT 无 stderr 输出。断言收敛为不变式：后缀出现
    // 与否 ⇔ stderrTail 非空。
    const tailEmpty = (transport.stderrTail ?? "").trim() === "";
    expect(/\(stderr:/.test(err.message)).toBe(!tailEmpty);
  });

  it("失败后 client 未挂载", async () => {
    const transport = new StdioTransport({ command: "dsh-mcp-missing-cmd-xyz" });
    const client = new MCPClient(transport);
    await client.initialize().catch(() => {});
    expect(client.client).toBeUndefined();
  });
});

