/**
 * dsh-mcp-servers — 客户端 core 层纯函数单元测试（`src/client/core/`）。
 *
 * 直连 src（无 React / DOM 依赖），覆盖两组「措辞容易写错、错了就静默出错」的契约：
 *
 * 1. **文本 ⇄ 结构化配置的互逆性**（`args.ts`）：`splitArgs(formatArgs(args))` 必须
 *    逐项还原 `args`，否则「打开编辑页 → 直接保存」就会改写用户配置。历史缺陷：
 *    含空格的段丢引号（往返被切成两段）、含双引号的段被 `\"` 转义后又被不认转义的
 *    splitArgs 拆开、空串参数被 join 成连续空格而丢失。
 * 2. **cwd 查询参数绝不进 pathname**（`api.ts`）：宿主 10 条路由全是 exact 命中，
 *    `cwd` 一旦被拼进 pathname，请求就落到前端静态 fallback 并以 405 空响应失败。
 *    历史缺陷：对无 query 的路径手拼 `cwdQueryOf()`（返回 `&cwd=…`）。
 */
import { describe, expect, it } from "vitest";
import {
  formatArgs,
  formatKeyValueLines,
  parseKeyValueLines,
  splitArgs,
  stableJson,
} from "../../src/client/core/args.ts";
import { cwdQueryOf, withCwd } from "../../src/client/core/api.ts";

describe("splitArgs", () => {
  it("按空格拆分裸参数", () => {
    expect(splitArgs("serve --mcp")).toEqual(["serve", "--mcp"]);
  });

  it("双引号包裹的段保留内部空格", () => {
    expect(splitArgs('--cwd "C:/my dir/x" -v')).toEqual(["--cwd", "C:/my dir/x", "-v"]);
  });

  it("引号内的 \\\" 与 \\\\ 是转义", () => {
    expect(splitArgs('--pattern "a\\"b"')).toEqual(["--pattern", 'a"b']);
    expect(splitArgs('"a\\\\b"')).toEqual(["a\\b"]);
  });

  it("空串与空输入", () => {
    expect(splitArgs("")).toEqual([]);
    expect(splitArgs('""')).toEqual([""]);
  });

  it("未加引号的段里的引号不当作分隔（向后兼容）", () => {
    expect(splitArgs("a\"b")).toEqual(['a"b']);
  });
});

describe("formatArgs / splitArgs 互逆（往返保真）", () => {
  const cases: Array<[string, string[]]> = [
    ["空数组", []],
    ["普通参数", ["serve", "--mcp"]],
    ["含空格的参数", ["C:/my dir/x"]],
    ["含空格的参数 + 其他参数", ["--cwd", "C:/my dir/x", "-v"]],
    ["含双引号的参数", ['a"b']],
    ["含双引号 + 其他参数", ["--pattern", 'a"b']],
    ["仅双引号", ['"']],
    ["空字符串参数", [""]],
    ["空串与普通参数混合", ["--x", "", "--y"]],
    ["含反斜杠", ["C:\\path\\to\\bin"]],
    ["含反斜杠 + 空格", ["C:\\my dir\\bin"]],
    ["含制表符", ["a\tb"]],
    ["等号与空格混合", ["--env=K=V", "--name=my tool"]],
  ];

  for (const [label, args] of cases) {
    it(`${label}：format → split 原样还原`, () => {
      expect(splitArgs(formatArgs(args))).toEqual(args);
    });
  }

  it("稳定：formatArgs 自身幂等（format→split→format 与直接 format 等价）", () => {
    for (const [, args] of cases) {
      expect(formatArgs(splitArgs(formatArgs(args)))).toBe(formatArgs(args));
    }
  });

  it("undefined / 非数组回落空串", () => {
    expect(formatArgs(undefined)).toBe("");
  });
});

describe("parseKeyValueLines / formatKeyValueLines", () => {
  it("KEY=VALUE 解析（空行与 # 注释跳过）", () => {
    expect(parseKeyValueLines("# 注释\nA=1\n\nB=2", "=")).toEqual({ A: "1", B: "2" });
  });

  it("值两侧的引号被剥掉，等号右侧整体为值", () => {
    expect(parseKeyValueLines('TOKEN="a=b c"', "=")).toEqual({ TOKEN: "a=b c" });
  });

  it("空值保留键", () => {
    expect(parseKeyValueLines("A=", "=")).toEqual({ A: "" });
  });

  it("请求头用冒号分隔，值内的冒号不影响切分", () => {
    expect(parseKeyValueLines("X-Url: https://example.com/a", ":")).toEqual({ "X-Url": "https://example.com/a" });
  });

  it("对象 → 多行文本回显（undefined 回落空串）", () => {
    expect(formatKeyValueLines({ A: "1", B: "2" }, "=")).toBe("A=1\nB=2");
    expect(formatKeyValueLines(undefined, "=")).toBe("");
  });
});

describe("withCwd / cwdQueryOf：cwd 只做查询参数", () => {
  it("withCwd 给无 query 的路径补 ?", () => {
    expect(withCwd("/api/dsh-mcp-servers/tool-disable", "G:/my proj"))
      .toBe("/api/dsh-mcp-servers/tool-disable?cwd=G%3A%2Fmy%20proj");
  });

  it("withCwd 给已有 query 的路径接 &", () => {
    expect(withCwd("/api/x?name=a&scope=global", "G:/p")).toBe("/api/x?name=a&scope=global&cwd=G%3A%2Fp");
  });

  it("withCwd 无 cwd 时原样返回", () => {
    expect(withCwd("/api/x", undefined)).toBe("/api/x");
    expect(withCwd("/api/x?a=1", "")).toBe("/api/x?a=1");
  });

  it("不变量：cwd 永不进 pathname（宿主 exact 路由的硬前提）", () => {
    for (const base of ["/api/x", "/api/x?a=1", "/api/x?a=1&b=2"]) {
      const url = new URL(withCwd(base, "G:/my proj"), "http://127.0.0.1:3080");
      expect(url.pathname).toBe("/api/x");
      expect(url.searchParams.get("cwd")).toBe("G:/my proj");
    }
  });

  it("cwdQueryOf 以 & 开头（只能接在已有 ? 之后）", () => {
    expect(cwdQueryOf("G:/p")).toBe("&cwd=G%3A%2Fp");
    expect(cwdQueryOf(undefined)).toBe("");
  });
});

describe("stableJson", () => {
  it("键序无关", () => {
    expect(stableJson({ a: 1, b: 2 })).toBe(stableJson({ b: 2, a: 1 }));
  });

  it("数组保序，undefined 键被丢弃", () => {
    expect(stableJson({ a: [1, 2], b: undefined })).toBe('{"a":[1,2]}');
    expect(stableJson({ a: [1, 2] })).not.toBe(stableJson({ a: [2, 1] }));
  });

  it("嵌套结构稳定", () => {
    expect(stableJson({ x: { b: 1, a: 2 } })).toBe('{"x":{"a":2,"b":1}}');
  });
});

// @ts-nocheck
/**
 * dsh-mcp-servers — unit：执行管道域契约（#664 阶段 2）。
 *
 * 两路径（supervisor 直呼 / ws_mcp_call）同构契约：同一远端结果 → 同一工具契约
 * 投影（#512 单一事实源，pipeline/project.ts）。差异面显式排除三项并文档化：
 *   - timeout：supervisor 靠 SDK timeoutMs（无 withTimeout 层）；middleware 有
 *     withTimeout 兜底（+2s，C-ABT/D6 口径）——同构断言不覆盖超时；
 *   - redact：middleware 错误文案经 hostRedact（createRedactor），supervisor
 *     B8 修复后走日志脱敏面——同构断言只比投影白名单，不比文案；
 *   - stale：目录 TTL 过期前置提示仅 middleware 有——同构断言不覆盖。
 * 其余环节（arguments 归一 → callTool → 投影）输入同、输出同。
 *
 * 另含 supervisor 路径 stats 埋点契约（行为扩展声明，红测先行）：
 * execute 成功后必须 recordCall（现状缺失，commit3 修复）。
 */
import { describe, expect, it } from "vitest";
import { fakeMCPClient } from "../helpers.ts";

const {
  defaultCallResultFallbackText,
  msgOf,
  normalizeArguments,
  projectCallToolResult,
  buildToolDefinition,
} = await import("../../src/index.ts");

// 同一远端 CallToolResult 形态矩阵：两路径 handler 差异（文本渲染风格）之外，
// 投影产物（content / structuredContent 键集与值）必须一致。
const results = [
  { content: [{ type: "text", text: "ok" }], structuredContent: { a: 1 }, isError: false },
  { content: [], isError: false },
  { toolResult: { value: 42 }, isError: false }, // 无 content → 兜底分支
  { content: "not-an-array", isError: false }, // 协议违规形态 → 兜底分支
];
const supervisorHandlers = {
  // supervisor 风格：extractText 占位符渲染 + 截断（差异面仅文本，投影白名单同）
  errorText: (c) => `ERR:${c.length}`,
  fallbackText: (r) => JSON.stringify(r),
};
const middlewareHandlers = {
  // middleware 风格：msgOf + 保留远端原文
  errorText: (c) => `ws_mcp_call:远端错误:${msgOf(c)}`,
  fallbackText: (r) =>
    typeof r === "object" && r !== null && "content" in r && !Array.isArray(r.content)
      ? msgOf(r.content)
      : defaultCallResultFallbackText(r),
};

describe("两路径同构：投影面（#512 单一事实源）", () => {
  it("两路径投影键集合同构", () => {
    for (const result of results) {
      const viaSupervisor = projectCallToolResult(result, supervisorHandlers);
      const viaMiddleware = projectCallToolResult(result, middlewareHandlers);
      // 结构契约同构：键集合一致（structuredContent 只随输入存在）
      expect("structuredContent" in viaMiddleware).toBe("structuredContent" in viaSupervisor);
    }
  });

  it("structuredContent 值同构", () => {
    for (const result of results) {
      const viaSupervisor = projectCallToolResult(result, supervisorHandlers);
      const viaMiddleware = projectCallToolResult(result, middlewareHandlers);
      if ("structuredContent" in viaSupervisor) {
        expect(viaMiddleware.structuredContent).toEqual(viaSupervisor.structuredContent);
      }
    }
  });

  it("投影 content 为数组", () => {
    for (const result of results) {
      const viaSupervisor = projectCallToolResult(result, supervisorHandlers);
      expect(Array.isArray(viaSupervisor.content)).toBeTruthy();
    }
  });

  it("投影 content 块数同构", () => {
    // content 形态同构：数组 + 块数 + 块类型一致（渲染文本是 handler 注入的
    // 调用方差异面，允许不同——同构断言只比投影结构）
    for (const result of results) {
      const viaSupervisor = projectCallToolResult(result, supervisorHandlers);
      const viaMiddleware = projectCallToolResult(result, middlewareHandlers);
      expect(viaMiddleware.content.length).toBe(viaSupervisor.content.length);
    }
  });

  it("投影 content 块类型同构", () => {
    for (const result of results) {
      const viaSupervisor = projectCallToolResult(result, supervisorHandlers);
      const viaMiddleware = projectCallToolResult(result, middlewareHandlers);
      if (viaSupervisor.content.length > 0) {
        expect(viaMiddleware.content[0].type).toBe(viaSupervisor.content[0].type);
      }
    }
  });

  it("直通路径 content 逐字同构", () => {
    // 正常 content 直通路径（无渲染差异）→ 内容逐字一致
    for (const result of results) {
      const viaSupervisor = projectCallToolResult(result, supervisorHandlers);
      const viaMiddleware = projectCallToolResult(result, middlewareHandlers);
      if (Array.isArray(result.content) && result.isError !== true) {
        expect(viaMiddleware.content).toEqual(viaSupervisor.content);
      }
    }
  });

  it("isError:true → 两路径统一抛错（Error 形态）", () => {
    // isError:true → 两路径统一抛错（错误契约同构：Error 形态，非裸对象；
    // 具体文案是 handler 注入差异面，不强匹配）
    for (const handlers of [supervisorHandlers, middlewareHandlers]) {
      expect(
        () => projectCallToolResult({ content: [{ type: "text", text: "boom" }], isError: true }, handlers),
      ).toThrow(Error);
      expect(() => projectCallToolResult({ isError: true }, handlers)).toThrow(Error);
    }
  });
});

describe("两路径同构：args 面（middleware 归一化；supervisor 直传——同构点）", () => {
  it('normalizeArguments 解析 JSON 字符串为对象', () => {
    expect(normalizeArguments('{"a":1}')).toEqual({ a: 1 });
  });

  it("B14 数组归一无害空态", () => {
    expect(normalizeArguments("[1,2]")).toEqual({});
  });

  it("object 输入经 supervisor 对象化原样透传", () => {
    // supervisor 路径契约：execute 侧对象化（typeof args === object ? args : {}）——
    // 对 normalizeArguments 产物两路同构（object 输入原样透传）。
    const supShape = (args) => (typeof args === "object" && args !== null ? args : {});
    expect(supShape(normalizeArguments({ a: 1 }))).toEqual({ a: 1 });
  });

  it("JSON 字符串经两路归一后同构", () => {
    const supShape = (args) => (typeof args === "object" && args !== null ? args : {});
    expect(supShape(normalizeArguments('{"a":1}'))).toEqual({ a: 1 });
  });

  it("数组经两路同样归一无害空态", () => {
    const supShape = (args) => (typeof args === "object" && args !== null ? args : {});
    expect(supShape(normalizeArguments("[1,2]"))).toEqual({});
  });
});

